import React, {useEffect, useState} from "react";
import "./App.css";

function App(){

const [jobs,setJobs]=useState([]);

useEffect(()=>{

fetch("http://localhost:5000/api/jobs")

.then(res=>res.json())

.then(data=>{
setJobs(data);
});

},[]);


return(

<div>

<h1>CampusCareerHub</h1>

{jobs.map(job=>(

<div className="card">

<h3>{job.title}</h3>

<p>{job.company}</p>

<p>{job.location}</p>

<p>{job.jobType}</p>

<a href={job.applyLink}
target="_blank">
Apply
</a>

</div>

))}

</div>

);

}

export default App;
